local total_stats_map = {
    PacketsSent = true,
    PacketsReceived = true,
    BytesSent = true,
    BytesReceived = true,
    PacketsLost = true,
}

local function stats_get(mapping, param, key, parentkey)
    local uri_get=getParam(sip_maps)
    local uri = uri_get(mapping, "URI", key, parentkey)
    if uri == "" then
        return "0"
    end
    local value = 0
    local callnumber = conn:call("mmdbd.callnumber.statistics", "get", {["profile"]=uri})
    if callnumber then
        if param == "TotalCallTime" then
            value = tostring(callnumber[1]["callTime"]) or "0"
        else
            value = tostring(callnumber[1][param]) or "0"
        end
    end

    if param == "Overruns" or param == "Underruns" or param == "ResetStatistics" then
        value = "0"
    end

    if param == "ServerDownTime" then
        local config, name, ltype = getInfoFromKey(key, parentkey)
        local profiles = conn:call("mmpbx.profile", "get", {})
        value = profiles and profiles[name] and profiles[name]["serverDownTime"] or "0"
    end

    if total_stats_map[param] then
        local total_stats = conn:call("mmpbx.sipprofile.stats", "get", {["profile"]=uri})
        if total_stats and total_stats[1] then
            value = tostring(total_stats[1][param]) or "0"
        end
    else
        local rtp_session = conn:call("mmpbx.rtp.session", "list", {["rtcp"]="1", ["name"]=uri} )
        if rtp_session then
            local found = false
            for _, v in pairs (rtp_session) do
                for _key, tmp in pairs (v) do
                    if param == _key then
                        value = tostring(tmp)
                        found = true
                        break
                    end
                end
                if found == true then
                    break
                end
            end
        end
    end

    return tostring(value)
end

local function stats_getall(mapping, key, parentkey)
    local results = {
        IncomingCallsReceived = "0",
        IncomingCallsAnswered = "0",
        IncomingCallsConnected = "0",
        IncomingCallsFailed = "0",
        OutgoingCallsAttempted = "0",
        OutgoingCallsAnswered = "0",
        OutgoingCallsConnected = "0",
        OutgoingCallsFailed = "0",
        TotalCallTime = "0",
        CallsDropped = "0",
        PacketsSent  = "0",
        PacketsReceived  = "0",
        BytesSent  = "0",
        BytesReceived  = "0",
        PacketsLost  = "0",
        ReceivePacketLossRate  = "0",
        FarEndPacketLossRate  = "0",
        ReceiveInterarrivalJitter  = "0",
        FarEndInterarrivalJitter  = "0",
        RoundTripDelay  = "0",
        AverageReceiveInterarrivalJitter  = "0",
        AverageFarEndInterarrivalJitter  = "0",
        AverageRoundTripDelay  = "0",
        Overruns = "0",
        Underruns = "0",
        ResetStatistics = "0",
        ServerDownTime = "0",
    }
    local uri_get=getParam(sip_maps)
    local uri = uri_get(mapping, "URI", key, parentkey)
    if uri == "" then
        return results
    end

    local rtp_session = conn:call("mmpbx.rtp.session", "list", {["rtcp"]="1", ["name"]=uri} )
    if rtp_session then
       for _, v in pairs (rtp_session) do
	  for key, tmp in pairs (v) do
	     results[key] = tostring(tmp)
	  end
       end
    end

    local callnumber = conn:call("mmdbd.callnumber.statistics", "get", {["profile"]=uri} )
    if callnumber and callnumber[1] then
        for key, tmp in pairs (callnumber[1]) do
            if key  == "callTime" then
                results["TotalCallTime"] = tostring(callnumber[1]["callTime"]) or "0"
            else
                results[key] = tostring(tmp)
            end
        end
    end

    for k,v in pairs(results) do
        results[k] = tostring(v)
    end

    local total_stats = conn:call("mmpbx.sipprofile.stats", "get", {["profile"]=uri})
    if total_stats and total_stats[1] then
        for k, _ in pairs (total_stats_map) do
            results[k] = tostring(total_stats[1][k]) or "0"
        end
    end

    if param == "ServerDownTime" then
        local config, name, ltype = getInfoFromKey(key, parentkey)
        local profiles = conn:call("mmpbx.profile", "get", {})
        results.ServerDownTime = profiles and profiles[name] and profiles[name]["serverDownTime"] or "0"
    end

    return results
end

InternetGatewayDevice_Services_VoiceService_i_VoiceProfile_i_Line_i_Stats_.get = stats_get
InternetGatewayDevice_Services_VoiceService_i_VoiceProfile_i_Line_i_Stats_.getall = stats_getall
InternetGatewayDevice_Services_VoiceService_i_VoiceProfile_i_Line_i_Stats_.set = function(mapping, param, value, key, parentkey)
    local uri_get=getParam(sip_maps)
    local uri = uri_get(mapping, "URI", key, parentkey)
    if uri == "" then
        return nil, "Invalid parameter"
    end
    if param == "ResetStatistics" then
        conn:call("mmpbx.sipprofile.stats", "reset", {["profile"]=uri})
        return true
    end
end
register(InternetGatewayDevice_Services_VoiceService_i_VoiceProfile_i_Line_i_Stats_)


